namespace sv_46e641da3db94cf7802e9b392fdd89de.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_46e641da3db94cf7802e9b392fdd89de.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ───── Left Sidebar: Channel List ───── *@
    <aside class="chat-sidebar" style="width:20%;">
        <div class="sidebar-header">
            <h5>Channels</h5>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var ch in _channels)
                {
                    <li class="channel-item @(ch.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(ch)">
                        <div class="channel-name"># @ch.Name</div>
                        <div class="channel-desc">@Truncate(ch.Description, 40)</div>
                        @if (ch.UnreadCount > 0)
                        {
                            <span class="unread-badge">@ch.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ───── Main Message Area ───── *@
    <section class="chat-main" style="width:@(_threadOpen ? "55%" : "80%");">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h5># @_activeChannel.Name</h5>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => { if (_hoveredMessageId == msg.Id) _hoveredMessageId = null; }">
                            <div class="message-header">
                                <span class="msg-author">@msg.Author</span>
                                <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="msg-content">@msg.Content</div>

                            @* Reactions *@
                            @if (msg.Reactions?.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                                @onclick="() => AddReactionAsync(msg.Id, r.Emoji)">
                                            @r.Emoji @r.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @* Thread-starter indicator *@
                            @if (_threadSummaries.TryGetValue(msg.Id, out var ts))
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                    @ts.ReplyCount @(ts.ReplyCount == 1 ? "reply" : "replies")
                                </button>
                            }

                            @* Hover actions *@
                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">💬 Reply</button>
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-btn"
                                                    @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            @* Message input *@
            <div class="message-input-area">
                <textarea class="msg-textarea" rows="2" placeholder="Type a message…"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="OnMainKeyDown" />
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_newMessageText)"
                        @onclick="SendMainMessageAsync">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ───── Right Panel: Thread View ───── *@
    @if (_threadOpen)
    {
        <aside class="chat-thread" style="width:25%;">
            <div class="thread-header">
                <h6>Thread</h6>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            @if (_threadRootMessage is not null)
            {
                <div class="thread-root-quote">
                    <span class="msg-author">@_threadRootMessage.Author</span>
                    <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                    <div class="msg-content">@_threadRootMessage.Content</div>
                </div>
            }

            <div class="thread-messages">
                @if (_threadReplies is not null)
                {
                    @foreach (var reply in _threadReplies)
                    {
                        <div class="message-row thread-reply">
                            <div class="message-header">
                                <span class="msg-author">@reply.Author</span>
                                <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="msg-content">@reply.Content</div>

                            @if (reply.Reactions?.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in reply.Reactions)
                                    {
                                        <button class="reaction-badge"
                                                @onclick="() => AddReactionAsync(reply.Id, r.Emoji)">
                                            @r.Emoji @r.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="msg-textarea" rows="2" placeholder="Reply…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDown" />
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_threadReplyText)"
                        @onclick="SendThreadReplyAsync">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    // ── Data ──
    private List<Channel>? _channels;
    private Channel? _activeChannel;
    private int? _activeChannelId;
    private List<Message>? _messages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    // ── Thread ──
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;

    // ── UI state ──
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private string _newMessageText = "";
    private string _threadReplyText = "";
    private bool _loadingMore;
    private bool _allMessagesLoaded;
    private ElementReference _messageListRef;

    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    // ── Channel selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id)
            return;

        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = null;
        _allMessagesLoaded = false;
        _threadSummaries.Clear();

        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        if (_messages.Count < PageSize)
            _allMessagesLoaded = true;

        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelList();
        StateHasChanged();
        await ScrollToBottom();
    }

    // ── Messaging ──

    private async Task SendMainMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null)
            return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _newMessageText = "";
        _messages?.Add(msg);
        StateHasChanged();
        await ScrollToBottom();
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
        _threadReplyText = "";
        _threadReplies?.Add(reply);

        // Update thread summary in main view
        if (_threadSummaries.TryGetValue(_threadRootId.Value, out var existing))
        {
            _threadSummaries[_threadRootId.Value] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries[_threadRootId.Value] = new ThreadSummary(_threadRootId.Value, 1, reply.SentAt);
        }

        StateHasChanged();
    }

    // ── Thread panel ──

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
        _emojiPickerMessageId = null;
        StateHasChanged();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadReplies = null;
    }

    // ── Reactions ──

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh the message list to reflect the new reaction
        if (_activeChannelId is not null && _messages is not null)
        {
            var fresh = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
            _messages = fresh;
        }

        // Refresh thread replies if open
        if (_threadRootId is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootId.Value);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Infinite scroll (load older) ──

    private async Task OnMessageListScroll()
    {
        if (_loadingMore || _allMessagesLoaded || _messages is null || _activeChannelId is null)
            return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50)
            return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        if (older.Count < PageSize)
            _allMessagesLoaded = true;

        _messages.InsertRange(0, older);
        BuildThreadSummaries();
        _loadingMore = false;
        StateHasChanged();
    }

    // ── Keyboard shortcuts ──

    private async Task OnMainKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMainMessageAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Helpers ──

    private void BuildThreadSummaries()
    {
        if (_messages is null) return;

        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task RefreshChannelList()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        try
        {
            await JS.InvokeVoidAsync("eval",
                "(() => { const el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight; })()");
        }
        catch { /* element may not be rendered yet */ }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string Truncate(string text, int max) =>
        text.Length <= max ? text : text[..(max - 1)] + "…";
}

/* ── Layout shell ── */

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Sidebar ── */

.chat-sidebar {
    display: flex;
    flex-direction: column;
    background: #19171d;
    border-right: 1px solid #2c2d30;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #2c2d30;
}

