toolArgs.file_text:
/* ── Layout shell ── */

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Sidebar ── */

.chat-sidebar {
    display: flex;
    flex-direction: column;
    background: #19171d;
    border-right: 1px solid #2c2d30;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #2c2d30;
}

    .sidebar-header h5 {
        margin: 0;
        font-size: 1rem;
        font-weight: 700;
        color: #fff;
    }

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 0 8px;
    transition: background 0.12s;
    position: relative;
}

    .channel-item:hover {
        background: #27242c;
    }

    .channel-item.active {
        background: #1164a3;
        color: #fff;
    }

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #9a9b9e;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-item.active .channel-desc {
    color: #c8dff0;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
    line-height: 1.4;
    position: absolute;
    right: 12px;
    top: 8px;
}

/* ── Main area ── */

.chat-main {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: width 0.2s;
    background: #1a1d21;
}

.main-header {
    padding: 12px 20px;
    border-bottom: 1px solid #2c2d30;
    flex-shrink: 0;
}

    .main-header h5 {
        margin: 0;
        font-size: 1rem;
        font-weight: 700;
        color: #fff;
    }

.main-header-desc {
    font-size: 0.8rem;
    color: #9a9b9e;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #9a9b9e;
    font-size: 1.1rem;
}

/* ── Message list ── */

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #9a9b9e;
    font-size: 0.85rem;
}

.message-row {
    position: relative;
    padding: 6px 8px;
    border-radius: 6px;
    margin-bottom: 2px;
    transition: background 0.1s;
}

    .message-row:hover {
        background: #222529;
    }

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.msg-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

.msg-time {
    font-size: 0.75rem;
    color: #616061;
}

.msg-content {
    font-size: 0.9rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ── Reactions ── */

.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    background: #2c2d30;
    border: 1px solid #3a3b3e;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #d1d2d3;
    transition: background 0.12s;
}

    .reaction-badge:hover {
        background: #3a3b3e;
    }

/* ── Thread link ── */

.thread-link {
    background: none;
    border: none;
    color: #1d9bd1;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

    .thread-link:hover {
        text-decoration: underline;
    }

/* ── Hover action buttons ── */

.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #1a1d21;
    border: 1px solid #3a3b3e;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,.35);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #d1d2d3;
    font-size: 0.8rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
}

    .action-btn:hover {
        background: #2c2d30;
    }

/* ── Emoji picker ── */

.emoji-picker {
    position: absolute;
    right: 8px;
    top: 36px;
    display: flex;
    gap: 2px;
    background: #2c2d30;
    border: 1px solid #3a3b3e;
    border-radius: 8px;
    padding: 6px;
    box-shadow: 0 4px 12px rgba(0,0,0,.4);
    z-index: 11;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

    .emoji-btn:hover {
        background: #3a3b3e;
    }

/* ── Message input ── */

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2c2d30;
    flex-shrink: 0;
}

.msg-textarea {
    flex: 1;
    resize: none;
    background: #222529;
    border: 1px solid #3a3b3e;
    border-radius: 6px;
    padding: 8px 12px;
    color: #d1d2d3;
    font-size: 0.9rem;
    font-family: inherit;
}

    .msg-textarea::placeholder {
        color: #616061;
    }

    .msg-textarea:focus {
        outline: none;
        border-color: #1d9bd1;
    }

.send-btn {
    align-self: flex-end;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.12s;
}

    .send-btn:hover:not(:disabled) {
        background: #148567;
    }

    .send-btn:disabled {
        opacity: 0.4;
        cursor: default;
    }

/* ── Thread panel ── */

.chat-thread {
    display: flex;
    flex-direction: column;
    border-left: 1px solid #2c2d30;
    background: #222529;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
    flex-shrink: 0;
}

    .thread-header h6 {
        margin: 0;
        font-size: 1rem;
        font-weight: 700;
        color: #fff;
    }

.close-thread-btn {
    background: none;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
}

    .close-thread-btn:hover {
        background: #2c2d30;
        color: #fff;
    }

.thread-root-quote {
    background: #1a1d21;
    border-left: 3px solid #1d9bd1;
    margin: 12px 16px;
    padding: 8px 12px;
    border-radius: 4px;
    flex-shrink: 0;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding-left: 0;
}

/* ── Scrollbar styling ── */

.message-list::-webkit-scrollbar,
.thread-messages::-webkit-scrollbar,
.channel-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-track,
.thread-messages::-webkit-scrollbar-track,
.channel-list::-webkit-scrollbar-track {
    background: transparent;
}

.message-list::-webkit-scrollbar-thumb,
.thread-messages::-webkit-scrollbar-thumb,
.channel-list::-webkit-scrollbar-thumb {
    background: #3a3b3e;
    border-radius: 3px;
}

